#!/bin/bash
conf=/tmp/lab/msg.conf
load() { msg=$(cat "$conf"); echo "config is: $msg"; }
trap 'echo "SIGHUP: reloading"; load' HUP
load
while true; do sleep 0.2; done

#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static volatile sig_atomic_t hits;
static void handler(int sig) { (void)sig; hits++; }

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = handler;
    if (sigaction(SIGKILL, &sa, NULL) == -1)
        perror("sigaction(SIGKILL)");              /* SIGKILL cannot be caught */
    sigaction(SIGUSR1, &sa, NULL);

    sigset_t block, old;
    sigemptyset(&block);
    sigaddset(&block, SIGUSR1);
    sigprocmask(SIG_BLOCK, &block, &old);          /* hold SIGUSR1 back */

    for (int i = 0; i < 3; i++)
        raise(SIGUSR1);                            /* send ourselves three signals */
    system("grep -E '^Sig(Blk|Pnd|Cgt)' /proc/$PPID/status");

    sigprocmask(SIG_SETMASK, &old, NULL);          /* unblock: delivery happens now */
    printf("handler ran %d time(s) after 3 signals\n", (int)hits);
    return 0;
}
